// A recorded Page + Finding (generated by the real backend checker and guardrail)
// with a drawn page to show it on. Used by the demo mode and the D2 tests.
import type { CheckResult } from "../contract";
import recorded from "./recorded.json";

export const DEMO_RESULT = recorded as CheckResult;
export const DEMO_ASPECT = 4 / 3;

/** A notebook page drawn as SVG, lines placed at the recorded boxes. */
export function demoPageSvg(result: CheckResult = DEMO_RESULT): string {
  const W = 1200, H = 900;
  const rules = Array.from({ length: 16 }, (_, i) => {
    const y = 90 + i * 50;
    return `<line x1="0" y1="${y}" x2="${W}" y2="${y}" stroke="#b9cde0" stroke-width="2"/>`;
  }).join("");
  const text = result.page.steps
    .map((s) => {
      const [x, y, , h] = s.bbox;
      return `<text x="${x * W + 8}" y="${(y + h * 0.78) * H}" font-size="${h * H * 0.8}"
        font-family="'Segoe Print','Bradley Hand','Comic Sans MS',cursive" fill="#23324a">${s.latex
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")}</text>`;
    })
    .join("");
  const problem = result.page.problem
    ? `<text x="${0.12 * W}" y="${0.13 * H}" font-size="44" font-family="'Segoe Print','Bradley Hand',cursive"
        fill="#23324a">${result.page.problem}</text>`
    : "";
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}">
    <rect width="${W}" height="${H}" fill="#fbfaf5"/>${rules}
    <line x1="110" y1="0" x2="110" y2="${H}" stroke="#e7a5a5" stroke-width="3"/>${problem}${text}</svg>`;
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}
